CREATE TABLE tenants(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE actors(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, name text NOT NULL, role text NOT NULL CHECK(role IN ('operator','analyst')), UNIQUE(id,tenant_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, actor_id uuid NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(actor_id,tenant_id) REFERENCES actors(id,tenant_id));
CREATE TABLE rate_limits(bucket text PRIMARY KEY, count integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL);
CREATE TABLE tickets(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, number integer NOT NULL, family text NOT NULL CHECK(family IN ('billing','integration','configuration')), subject text NOT NULL, body text NOT NULL, customer text NOT NULL, email text NOT NULL, account_id uuid NOT NULL, scenario text NOT NULL, priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id));
CREATE TABLE runs(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, ticket_id uuid NOT NULL, actor_id uuid NOT NULL, provider text NOT NULL, model text, prompt_version text NOT NULL DEFAULT 'support-v1', status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','waiting_for_approval','completed','needs_human','failed','cancelled')), phase text NOT NULL DEFAULT 'investigate', lease_owner uuid, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, deadline timestamptz NOT NULL, checkpoint jsonb NOT NULL DEFAULT '{}', result jsonb NOT NULL DEFAULT '{}', error text, cancel_requested boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz, UNIQUE(id,tenant_id), FOREIGN KEY(ticket_id,tenant_id) REFERENCES tickets(id,tenant_id), FOREIGN KEY(actor_id,tenant_id) REFERENCES actors(id,tenant_id));
CREATE UNIQUE INDEX one_active_run ON runs(ticket_id) WHERE status IN ('queued','running','waiting_for_approval');
CREATE INDEX runs_queue ON runs(status,lease_until,created_at);
CREATE TABLE events(id bigserial PRIMARY KEY, tenant_id uuid NOT NULL, run_id uuid NOT NULL, kind text NOT NULL, title text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(run_id,tenant_id) REFERENCES runs(id,tenant_id));
CREATE INDEX events_stream ON events(run_id,id);
CREATE TABLE actions(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, run_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('reprocess_billing_event','retry_delivery')), target_id text NOT NULL, payload jsonb NOT NULL, digest text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','executing','succeeded','failed','rejected','stale','unknown','cancelled')), approved_by uuid, approved_at timestamptz, receipt jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id), FOREIGN KEY(run_id,tenant_id) REFERENCES runs(id,tenant_id), FOREIGN KEY(approved_by,tenant_id) REFERENCES actors(id,tenant_id));
CREATE FUNCTION immutable_proposal() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.kind IS DISTINCT FROM OLD.kind OR NEW.target_id IS DISTINCT FROM OLD.target_id OR NEW.payload IS DISTINCT FROM OLD.payload OR NEW.digest IS DISTINCT FROM OLD.digest OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.run_id IS DISTINCT FROM OLD.run_id THEN RAISE EXCEPTION 'Proposal payload is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER actions_immutable BEFORE UPDATE ON actions FOR EACH ROW EXECUTE FUNCTION immutable_proposal();
CREATE TABLE documents(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, source_key text NOT NULL, title text NOT NULL, version text NOT NULL, product_version text NOT NULL, body text NOT NULL, search tsvector GENERATED ALWAYS AS (to_tsvector('english',title || ' ' || body)) STORED, UNIQUE(tenant_id,source_key,version));
CREATE INDEX documents_search ON documents USING gin(search);
CREATE TABLE audit(id bigserial PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, actor_id uuid, verb text NOT NULL, object_id text NOT NULL, trace_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_calls(id bigserial PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs, model text NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, cost numeric, duration_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
